import {state,save,uid,dateKey,currentProfile} from './store.js';let dbPromise;const allowed=/\.(pdf|docx|epub|txt)$/i;
function db(){return dbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('bibaboo-library',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function operation(mode,fn){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('files',mode),r=fn(tx.objectStore('files'));let result;r.onsuccess=()=>result=r.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
const fileKey=id=>`${currentProfile()?.profileId||'none'}:${id}`;
export async function importFiles(files){let added=0,skipped=0;for(const file of files){if(!allowed.test(file.name)||file.size>30*1024*1024||state.files.some(f=>f.name===file.name&&f.size===file.size&&f.modified===file.lastModified)){skipped++;continue}const id=uid();await operation('readwrite',s=>s.put(file,fileKey(id)));state.files.push({id,profileId:currentProfile().profileId,name:file.name,size:file.size,modified:file.lastModified,type:file.name.split('.').pop().toUpperCase(),category:'论文',tags:'',added:dateKey(),lastOpened:null});if(!save())throw Error('文件已存入浏览器，但目录信息保存失败。请导出备份并释放空间。');added++}return {added,skipped}}
export async function connectFolder(){if(!window.showDirectoryPicker)throw Error('当前浏览器不支持文件夹授权，请使用文件选择或拖拽。');const handle=await window.showDirectoryPicker({mode:'read'});const files=[];async function walk(dir,depth=0){if(depth>8)return;for await(const item of dir.values()){if(item.kind==='file'&&allowed.test(item.name))files.push(await item.getFile());else if(item.kind==='directory')await walk(item,depth+1)}}await walk(handle);return importFiles(files)}
export async function getFile(id){const scoped=await operation('readonly',s=>s.get(fileKey(id)));if(scoped)return scoped;return currentProfile()?.migratedFrom?operation('readonly',s=>s.get(id)):null}
export async function deleteFile(id){await operation('readwrite',s=>s.delete(fileKey(id)));if(currentProfile()?.migratedFrom)await operation('readwrite',s=>s.delete(id));state.files=state.files.filter(f=>f.id!==id);state.papers.forEach(p=>{if(p.fileId===id)p.fileId=''});save()}
export async function purgeProfileFiles(profileId,ids=[]){for(const id of ids){await operation('readwrite',s=>s.delete(`${profileId}:${id}`));await operation('readwrite',s=>s.delete(id))}}
export async function purgeAllAppFiles(){const d=await db();await new Promise((resolve,reject)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
